import { pillarStyles } from '../../../constants';
import { Pillar } from '../../../domain';
import {
  StyledPillarCard,
  StyledTitle,
  StyledTotalTrainings,
} from './PillarCard.styles';

interface PillarCardProps {
  pillar: Pillar;
  onClick: () => void;
}

export const PillarCard = ({ pillar, onClick }: PillarCardProps) => {
  const pillarColor = pillarStyles[pillar.id as keyof typeof pillarStyles];

  return (
    <StyledPillarCard
      style={{ backgroundColor: pillarColor.background }}
      onClick={onClick}
    >
      <StyledTitle>{pillar.name}</StyledTitle>
      <StyledTotalTrainings>
        {pillar.trainings.length} trainings
      </StyledTotalTrainings>
    </StyledPillarCard>
  );
};

export default PillarCard;
